MATCH (e:Employee)
WHERE (
    (e)-[:CURRENTLY_IN_DEPARTMENT]->(:Department)
    OR (e)-[:CURRENTLY_IN_POSITION]->(:Position)
  )
AND NOT EXISTS {
    MATCH (e)-[:HAS_PERFORMANCE]->(p:PerformanceAssessment)
    WHERE p.assessment_year = '2024年'
}
RETURN count(DISTINCT e) AS employee_count
